// Let's use reflection to find the actual API
using System.Reflection;
var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/modelcontextprotocol/1.4.0/lib/net9.0/ModelContextProtocol.dll");

// McpServerResourceAttribute
var attr = asm.GetType("ModelContextProtocol.Server.McpServerResourceAttribute");
if (attr != null) {
    Console.WriteLine("=== McpServerResourceAttribute ===");
    foreach (var p in attr.GetProperties()) Console.WriteLine($"  Property: {p.Name} : {p.PropertyType.Name}");
    foreach (var c in attr.GetConstructors()) {
        var pars = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  Ctor: ({pars})");
    }
}

var typeAttr = asm.GetType("ModelContextProtocol.Server.McpServerResourceTypeAttribute");
if (typeAttr != null) {
    Console.WriteLine("=== McpServerResourceTypeAttribute ===");
    foreach (var p in typeAttr.GetProperties()) Console.WriteLine($"  Property: {p.Name} : {p.PropertyType.Name}");
}

// McpServerResource abstract class
var res = asm.GetType("ModelContextProtocol.Server.McpServerResource");
if (res != null) {
    Console.WriteLine("=== McpServerResource ===");
    foreach (var m in res.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)) {
        Console.WriteLine($"  Method: {m.Name} returns {m.ReturnType.Name}");
    }
    foreach (var p in res.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)) {
        Console.WriteLine($"  Property: {p.Name} : {p.PropertyType.Name}");
    }
}

// WithResources extension methods
var extType = asm.GetTypes().FirstOrDefault(t => t.Name == "McpServerBuilderExtensions");
if (extType != null) {
    foreach (var m in extType.GetMethods().Where(m => m.Name.Contains("Resource"))) {
        var pars = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"Extension: {m.Name}({pars})");
    }
}
EOF
