public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-config", MimeType = "application/json"),
     Description("Returns application configuration data.")]
    public static string GetAppConfig()
    {
        return """
            {
              "appName": "McpHttpServer",
              "version": "1.0.0",
              "features": {
                "loggingEnabled": true,
                "maxConnections": 100
              }
            }
            """;
    }
}

