using ModelContextProtocol.Server;

namespace McpHttpServer.Resources;

public class ConfigResource : McpServerResource
{
    public ConfigResource()
    {
        Name = "app-config";
        Description = "Returns application configuration data.";
        Uri = "config://app/settings";
        MimeType = "application/json";
    }

    public override ValueTask<McpServerResourceContent> ReadAsync(
        RequestContext<object> context, CancellationToken cancellationToken = default)
    {
        var configJson = """
            {
              "appName": "McpHttpServer",
              "version": "1.0.0",
              "features": {
